//! Re-implementation of the ColorSpace C++ header's color types and
//! conversions, using f32 arithmetic to match the original's float
//! precision behavior bit-for-bit.

#[derive(Debug, Clone, Copy)]
pub struct Rgb {
    pub r: f32,
    pub g: f32,
    pub b: f32,
}

impl Rgb {
    pub fn new(r: f32, g: f32, b: f32) -> Self {
        Rgb { r, g, b }
    }
}

#[derive(Debug, Clone, Copy)]
pub struct Hsl {
    pub h: f32,
    pub s: f32,
    pub l: f32,
}

#[derive(Debug, Clone, Copy)]
pub struct Hsv {
    pub h: f32,
    pub s: f32,
    pub v: f32,
}

#[derive(Debug, Clone, Copy)]
pub struct Cmyk {
    pub c: f32,
    pub m: f32,
    pub y: f32,
    pub k: f32,
}

#[derive(Debug, Clone, Copy)]
pub struct Yuv {
    pub y: f32,
    pub u: f32,
    pub v: f32,
}

pub struct ColorConverter;

impl ColorConverter {
    pub fn rgb_to_hsl(rgb: &Rgb) -> Hsl {
        let r = rgb.r;
        let g = rgb.g;
        let b = rgb.b;
        let max = r.max(g).max(b);
        let min = r.min(g).min(b);
        let d = max - min;

        let l = (max + min) / 2.0;

        let (mut h, mut s) = (0.0f32, 0.0f32);
        if d != 0.0 {
            s = d / (1.0 - (2.0 * l - 1.0).abs());
            if max == r {
                h = 60.0 * (((g - b) / d) % 6.0);
            } else if max == g {
                h = 60.0 * ((b - r) / d + 2.0);
            } else {
                h = 60.0 * ((r - g) / d + 4.0);
            }
        }
        if h < 0.0 {
            h += 360.0;
        }
        Hsl { h, s, l }
    }

    pub fn rgb_to_hsv(rgb: &Rgb) -> Hsv {
        let r = rgb.r;
        let g = rgb.g;
        let b = rgb.b;
        let max = r.max(g).max(b);
        let min = r.min(g).min(b);
        let d = max - min;

        let v = max;

        let (mut h, mut s) = (0.0f32, 0.0f32);
        if d != 0.0 {
            s = d / max;
            if max == r {
                h = 60.0 * (((g - b) / d) % 6.0);
            } else if max == g {
                h = 60.0 * ((b - r) / d + 2.0);
            } else {
                h = 60.0 * ((r - g) / d + 4.0);
            }
        }
        if h < 0.0 {
            h += 360.0;
        }
        Hsv { h, s, v }
    }

    pub fn rgb_to_cmyk(rgb: &Rgb) -> Cmyk {
        let k = 1.0 - rgb.r.max(rgb.g).max(rgb.b);
        if k == 1.0 {
            return Cmyk {
                c: 0.0,
                m: 0.0,
                y: 0.0,
                k,
            };
        }
        let d = 1.0 - k;
        Cmyk {
            c: (1.0 - rgb.r - k) / d,
            m: (1.0 - rgb.g - k) / d,
            y: (1.0 - rgb.b - k) / d,
            k,
        }
    }

    pub fn rgb_to_yuv(rgb: &Rgb) -> Yuv {
        Yuv {
            y: 0.299f32 * rgb.r + 0.587f32 * rgb.g + 0.114f32 * rgb.b,
            u: -0.147f32 * rgb.r - 0.289f32 * rgb.g + 0.436f32 * rgb.b,
            v: 0.615f32 * rgb.r - 0.515f32 * rgb.g - 0.1f32 * rgb.b,
        }
    }
}

//! Reproduces C++ `std::ostream <<` default formatting for floating-point
//! values: `std::defaultfloat` with precision 6, i.e. printf's `%g`.

/// Format an f32 exactly as `std::cout << value` would with default settings.
pub fn format_f32(value: f32) -> String {
    if value.is_nan() {
        return if value.is_sign_negative() {
            "-nan".to_string()
        } else {
            "nan".to_string()
        };
    }
    if value.is_infinite() {
        return if value < 0.0 { "-inf" } else { "inf" }.to_string();
    }

    let negative = value.is_sign_negative();
    let abs = if negative { -value } else { value };

    let body = if abs == 0.0 {
        "0".to_string()
    } else {
        format_g(abs)
    };

    if negative {
        format!("-{}", body)
    } else {
        body
    }
}

/// %g formatting (6 significant digits) of a positive, finite, non-zero f32.
fn format_g(x: f32) -> String {
    // Round to 6 significant digits using Rust's correctly-rounded
    // scientific formatting, e.g. "2.23517e-8".
    let sci = format!("{:.5e}", x);
    let (mantissa, exp_str) = sci.split_once('e').unwrap();
    let exp: i32 = exp_str.parse().unwrap();
    let digits: String = mantissa.chars().filter(|c| c.is_ascii_digit()).collect();
    debug_assert_eq!(digits.len(), 6);

    if exp < -4 || exp >= 6 {
        // Scientific notation: d[.ddd]e±XX (exponent at least two digits).
        let mut m: String = digits.trim_end_matches('0').to_string();
        if m.len() > 1 {
            m.insert(1, '.');
        }
        let sign = if exp < 0 { '-' } else { '+' };
        format!("{}e{}{:02}", m, sign, exp.abs())
    } else if exp >= 0 {
        // Fixed notation, decimal point after exp+1 digits.
        let int_len = (exp + 1) as usize;
        let frac: &str = digits[int_len..].trim_end_matches('0');
        if frac.is_empty() {
            digits[..int_len].to_string()
        } else {
            format!("{}.{}", &digits[..int_len], frac)
        }
    } else {
        // 0.000ddd style: -4 <= exp < 0.
        let zeros = (-exp - 1) as usize;
        let frac: &str = digits.trim_end_matches('0');
        format!("0.{}{}", "0".repeat(zeros), frac)
    }
}

mod color;
mod cppfmt;

use color::{ColorConverter, Rgb};
use cppfmt::format_f32;

/// Mimics C++ `std::stof`: skips leading whitespace, parses the longest
/// valid floating-point prefix, and panics if there is none.
fn stof(s: &str) -> f32 {
    let s = s.trim_start();
    let bytes = s.as_bytes();
    let mut end = 0;
    let mut seen_digit = false;

    // Optional sign.
    if end < bytes.len() && (bytes[end] == b'+' || bytes[end] == b'-') {
        end += 1;
    }
    // Integer and fraction digits with at most one decimal point.
    while end < bytes.len() && bytes[end].is_ascii_digit() {
        end += 1;
        seen_digit = true;
    }
    if end < bytes.len() && bytes[end] == b'.' {
        end += 1;
        while end < bytes.len() && bytes[end].is_ascii_digit() {
            end += 1;
            seen_digit = true;
        }
    }
    if !seen_digit {
        panic!("std::stof: no conversion could be performed");
    }
    // Optional exponent, only if it has digits.
    if end < bytes.len() && (bytes[end] == b'e' || bytes[end] == b'E') {
        let mut e = end + 1;
        if e < bytes.len() && (bytes[e] == b'+' || bytes[e] == b'-') {
            e += 1;
        }
        let digits_start = e;
        while e < bytes.len() && bytes[e].is_ascii_digit() {
            e += 1;
        }
        if e > digits_start {
            end = e;
        }
    }
    s[..end].parse::<f32>().expect("std::stof: out of range")
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut r = 0.4f32;
    let mut g = 0.2f32;
    let mut b = 0.8f32;

    if args.len() > 3 {
        r = stof(&args[1]);
        g = stof(&args[2]);
        b = stof(&args[3]);
    }

    let rgb = Rgb::new(r, g, b);

    let hsl = ColorConverter::rgb_to_hsl(&rgb);
    let hsv = ColorConverter::rgb_to_hsv(&rgb);
    let cmyk = ColorConverter::rgb_to_cmyk(&rgb);
    let yuv = ColorConverter::rgb_to_yuv(&rgb);

    println!(
        "{} {} {} {} {} {} {} {} {} {} {} {} {}",
        format_f32(hsl.h),
        format_f32(hsl.s),
        format_f32(hsl.l),
        format_f32(hsv.h),
        format_f32(hsv.s),
        format_f32(hsv.v),
        format_f32(cmyk.c),
        format_f32(cmyk.m),
        format_f32(cmyk.y),
        format_f32(cmyk.k),
        format_f32(yuv.y),
        format_f32(yuv.u),
        format_f32(yuv.v),
    );
}

