            fixup(match branch {
                1 => 60.0 * (q % 6.0),
                2 => 60.0 * (q + 2.0),
                _ => 60.0 * (q + 4.0),
            })
        }));
        // H3: all f32
        h_vals.push(g32(if branch == 0 {
            0.0
        } else {
            fixup32(match branch {
                1 => 60.0 * (q32 % 6.0),
                2 => 60.0 * (q32 + 2.0),
                _ => 60.0 * (q32 + 4.0),
            })
        }));
        // H4: f32 division, f32 fmod/offset, f64 scale
        h_vals.push(g64(if branch == 0 {
            0.0
        } else {
            let t = match branch {
                1 => q32 % 6.0,
                2 => q32 + 2.0,
                _ => q32 + 4.0,
            };
            fixup(60.0 * (t as f64))
        }));
        // H5: f64 numerator over d32, f64 rest
        h_vals.push(g64(if branch == 0 {
            0.0
        } else {
            let q = num64 / (d32 as f64);
            fixup(match branch {
                1 => 60.0 * (q % 6.0),
                2 => 60.0 * (q + 2.0),
                _ => 60.0 * (q + 4.0),
            })
        }));
        // H1c: H1 cast f32
        h_vals.push(g32(if branch == 0 {
            0.0
        } else {
            let q = num64 / d64;
            fixup(match branch {
                1 => 60.0 * (q % 6.0),
                2 => 60.0 * (q + 2.0),
                _ => 60.0 * (q + 4.0),
            }) as f32
        }));
        // H2c: H2 cast f32
        h_vals.push(g32(if branch == 0 {
            0.0
        } else {
            let q = q32 as f64;
            fixup(match branch {
                1 => 60.0 * (q % 6.0),
                2 => 60.0 * (q + 2.0),
                _ => 60.0 * (q + 4.0),
            }) as f32
        }));
        // H5c: H5 cast f32
        h_vals.push(g32(if branch == 0 {
            0.0
        } else {
            let q = num64 / (d32 as f64);
            fixup(match branch {
                1 => 60.0 * (q % 6.0),
                2 => 60.0 * (q + 2.0),
                _ => 60.0 * (q + 4.0),
            }) as f32
        }));
        let off2 = off + s_models.len();
        for (i, v) in h_vals.iter().enumerate() {
            if v != toks[0] {
                counts[off2 + i] += 1;
            }
            if v != toks[3] {
                h2counts[i] += 1;
            }
        }

        // ---- hsv.s models ----
        let mut v_vals: Vec<String> = Vec::new();
        let guard = |f: &dyn Fn() -> f64| -> f64 {
            if max32 != 0.0 {
                f()
            } else {
                0.0
            }
        };
        v_vals.push(g64(guard(&|| d64 / max64))); // V1
        v_vals.push(g64(guard(&|| (d32 as f64) / max64))); // V2
        v_vals.push(g32(if max32 != 0.0 { d32 / max32 } else { 0.0 })); // V3
        v_vals.push(g32(if max32 != 0.0 {
            (d64 / max64) as f32
        } else {
            0.0
        })); // V4
        v_vals.push(g32(if max32 != 0.0 {
            (d64 / max64) as f32
        } else {
            0.0
        })); // V1c dup of V4
        v_vals.push(g32(if max32 != 0.0 {
            ((d32 as f64) / max64) as f32
        } else {
            0.0
        })); // V2c
        let off3 = off2 + h_models.len();
        for (i, v) in v_vals.iter().enumerate() {
            if v != toks[4] {
                counts[off3 + i] += 1;
            }
        }
    }

    let mut idx = 0;
    println!("--- hsl.l ---");
    for (i, n) in l_models.iter().enumerate() {
        println!("{:14} mismatches: {}", n, counts[idx + i]);
    }
    idx += l_models.len();
    println!("--- hsl.s ---");
    for (i, n) in s_models.iter().enumerate() {
        println!("{:14} mismatches: {}", n, counts[idx + i]);
    }
    idx += s_models.len();
    println!("--- hsl.h ---");
    for (i, n) in h_models.iter().enumerate() {
        println!("{:14} mismatches: {}", n, counts[idx + i]);
    }
    idx += h_models.len();
    println!("--- hsv.h ---");
    for (i, n) in h_models.iter().enumerate() {
        println!("{:14} mismatches: {}", n, h2counts[i]);
    }
    println!("--- hsv.s ---");
    for (i, n) in v_models.iter().enumerate() {
        println!("{:14} mismatches: {}", n, counts[idx + i]);
    }
}

