use std::fs;

fn g64(value: f64) -> String {
    if value.is_nan() {
        return "nan".into();
    }
    if value.is_infinite() {
        return if value < 0.0 { "-inf" } else { "inf" }.into();
    }
    let negative = value.is_sign_negative();
    let abs = if negative { -value } else { value };
    let body = if abs == 0.0 { "0".to_string() } else { pos(abs) };
    if negative {
        format!("-{}", body)
    } else {
        body
    }
}
fn g32(v: f32) -> String {
    g64(v as f64)
}
fn pos(x: f64) -> String {
    let sci = format!("{:.5e}", x);
    let (mantissa, exp_str) = sci.split_once('e').unwrap();
    let exp: i32 = exp_str.parse().unwrap();
    let digits: String = mantissa.chars().filter(|c| c.is_ascii_digit()).collect();
    if exp < -4 || exp >= 6 {
        let mut m: String = digits.trim_end_matches('0').to_string();
        if m.len() > 1 {
            m.insert(1, '.');
        }
        let sign = if exp < 0 { '-' } else { '+' };
        format!("{}e{}{:02}", m, sign, exp.abs())
    } else if exp >= 0 {
        let int_len = (exp + 1) as usize;
        let frac: &str = digits[int_len..].trim_end_matches('0');
        if frac.is_empty() {
            digits[..int_len].to_string()
        } else {
            format!("{}.{}", &digits[..int_len], frac)
        }
    } else {
        let zeros = (-exp - 1) as usize;
        let frac: &str = digits.trim_end_matches('0');
        format!("0.{}{}", "0".repeat(zeros), frac)
    }
}

fn main() {
    let data = fs::read_to_string("/tmp/corpus.txt").unwrap();

    // hue model: (num_src, d_src, div32, mult32, add_before, store32)
    // add_before: true => q+offset (or q+6 if neg) then *60; false => 60*q then +offset*60/fixup
    let mut s_counts = vec![0usize; 64];
    let mut h_counts = vec![0usize; 64];

    for line in data.lines() {
        let parts: Vec<&str> = line.split(" | ").collect();
        let inp: Vec<f32> = parts[0].split_whitespace().map(|s| s.parse().unwrap()).collect();
        let toks: Vec<&str> = parts[1].split_whitespace().collect();
        let (r, g, b) = (inp[0], inp[1], inp[2]);
        let max32 = r.max(g).max(b);
        let min32 = r.min(g).min(b);
        let d32 = max32 - min32;
        let sum32 = max32 + min32;
        let d64 = max32 as f64 - min32 as f64;
        let sum64 = max32 as f64 + min32 as f64;

        // ---- hsl.s combos ----
        // bits: num32(1) | sum32(1) | denom_f1(1) | div32(1) | store32(1)
        for num_src in 0..2 {
            let num64v = if num_src == 0 { d32 as f64 } else { d64 };
            for sum_src in 0..2 {
                let sumv = if sum_src == 0 { sum32 as f64 } else { sum64 };
                for denom_kind in 0..2 {
                    // 0: branch formula (l<0.5 => sum else 2-sum); 1: 1-|sum-1|
                    let denom64 = if denom_kind == 0 {
                        if sumv / 2.0 < 0.5 {
                            sumv
                        } else {
                            2.0 - sumv
                        }
                    } else {
                        1.0 - (sumv - 1.0).abs()
                    };
                    for div32 in 0..2 {
                        let val64 = if div32 == 1 {
                            (num64v as f32 / denom64 as f32) as f64
                        } else {
                            num64v / denom64
                        };
                        for store32 in 0..2 {
                            let s = if d32 != 0.0 { val64 } else { 0.0 };
                            let out = if store32 == 1 { g32(s as f32) } else { g64(s) };
                            let idx = num_src * 16 + sum_src * 8 + denom_kind * 4 + div32 * 2 + store32;
                            if out != toks[1] {
                                s_counts[idx] += 1;
                            }
                        }
                    }
                }
            }
        }

        // ---- hue combos ----
        let branch = if max32 == min32 {
            0
        } else if max32 == r {
            1
        } else if max32 == g {
            2
        } else {
            3
        };
        let num32v = match branch {
            1 => g - b,
            2 => b - r,
            3 => r - g,
            _ => 0.0,
        };
        let num64v = match branch {
            1 => g as f64 - b as f64,
            2 => b as f64 - r as f64,
            3 => r as f64 - g as f64,
            _ => 0.0,
        };
        let offset = match branch {
            1 => 0.0,
            2 => 120.0,
            _ => 240.0,
        };
        // bits: num32 | ddash32 | div32 | mult32 | add_before | store32
        for num_src in 0..2 {
            for d_src in 0..2 {
                for div32 in 0..2 {
                    // compute q in both f32 and f64 views
                    let q64 = {
                        let n = if num_src == 0 { num32v as f64 } else { num64v };
                        let d = if d_src == 0 { d32 as f64 } else { d64 };
                        if div32 == 1 {
                            ((n as f32) / (d as f32)) as f64
                        } else {
                            n / d
                        }
                    };
                    let q32v = q64 as f32; // used when mult32
                    for mult32 in 0..2 {
                        for add_before in 0..2 {
                            for store32 in 0..2 {
                                let h64 = if branch == 0 {
                                    0.0
                                } else if mult32 == 1 {
                                    let q = q32v;
                                    let mut h = if add_before == 1 {
                                        let t = if branch == 1 {
                                            if q < 0.0 {
                                                q + 6.0
                                            } else {
                                                q
                                            }
                                        } else if branch == 2 {
                                            q + 2.0
                                        } else {
                                            q + 4.0
                                        };
                                        60.0f32 * t
                                    } else {
                                        60.0f32 * q + (offset as f32)
                                    };
                                    if add_before != 1 && branch == 1 && h < 0.0 {
                                        h += 360.0;
                                    }
                                    h as f64
                                } else {
                                    let q = q64;
                                    let mut h = if add_before == 1 {
                                        let t = if branch == 1 {
                                            let m = q % 6.0;
                                            m
                                        } else if branch == 2 {
                                            q + 2.0
                                        } else {
                                            q + 4.0
                                        };
                                        60.0f64 * t
                                    } else {
                                        60.0f64 * q + offset
                                    };
                                    if h < 0.0 {
                                        h += 360.0;
                                    }
                                    h
                                };
                                let out = if store32 == 1 {
                                    g32(h64 as f32)
                                } else {
                                    g64(h64)
                                };
                                let idx = num_src * 32
                                    + d_src * 16
                                    + div32 * 8
                                    + mult32 * 4
                                    + add_before * 2
                                    + store32;
                                if out != toks[0] {
                                    h_counts[idx] += 1;
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    println!("--- hsl.s combos (num32 sum32 denomF1 div32 store32), 1500 cases ---");
    let mut idxs: Vec<usize> = (0..64).collect();
    idxs.sort_by_key(|&i| s_counts[i]);
    for &i in idxs.iter().take(8) {
        println!(
            "num32={} sum32={} f1={} div32={} store32={}: {}",
            i / 16,
            (i / 8) % 2,
            (i / 4) % 2,
            (i / 2) % 2,
            i % 2,
            s_counts[i]
        );
    }
    println!("--- hue combos (num32 d32 div32 mult32 add_before store32) ---");
    let mut idxs: Vec<usize> = (0..64).collect();
    idxs.sort_by_key(|&i| h_counts[i]);
    for &i in idxs.iter().take(8) {
        println!(
            "num32={} d32={} div32={} mult32={} add_before={} store32={}: {}",
            i / 32,
            (i / 16) % 2,
            (i / 8) % 2,
            (i / 4) % 2,
            (i / 2) % 2,
            i % 2,
            h_counts[i]
        );
    }
}

