        (0.7310492, 1.012019, 0.4271395, "88.8233"),
    ];
    for (r,g,b, refh) in cases {
        let max32 = r.max(g).max(b);
        let min32 = r.min(g).min(b);
        let d32 = max32 - min32;
        let d64 = max32 as f64 - min32 as f64;
        let branch = if max32 == r {1} else if max32 == g {2} else {3};
        let num32 = match branch { 1 => g - b, 2 => b - r, _ => r - g };
        let num64 = match branch { 1 => g as f64 - b as f64, 2 => b as f64 - r as f64, _ => r as f64 - g as f64 };
        let off = match branch {1 => 0.0, 2 => 2.0, _ => 4.0};
        println!("case ref={} branch={} num32={:.10e} num64={:.12e} d32={:.10e} d64={:.12e}", refh, branch, num32, num64, d32, d64);
