//! Re-implementation of the ColorSpace C++ library's color types and
//! conversions. All arithmetic is f32 and mirrors the original operation
//! order exactly (verified against the reference binary), including
//! std::max/std::min comparison semantics for signed zeros.

/// C++ `std::max<float>(a, b)` = `(a < b) ? b : a`.
fn cpp_max(a: f32, b: f32) -> f32 {
    if a < b {
        b
    } else {
        a
    }
}

/// C++ `std::min<float>(a, b)` = `(b < a) ? b : a`.
fn cpp_min(a: f32, b: f32) -> f32 {
    if b < a {
        b
    } else {
        a
    }
}

#[derive(Debug, Clone, Copy)]
pub struct Rgb {
    pub r: f32,
    pub g: f32,
    pub b: f32,
}

impl Rgb {
    pub fn new(r: f32, g: f32, b: f32) -> Self {
        Rgb { r, g, b }
    }
}

#[derive(Debug, Clone, Copy)]
pub struct Hsl {
    pub h: f32,
    pub s: f32,
    pub l: f32,
}

#[derive(Debug, Clone, Copy)]
pub struct Hsv {
    pub h: f32,
    pub s: f32,
    pub v: f32,
}

#[derive(Debug, Clone, Copy)]
pub struct Cmyk {
    pub c: f32,
    pub m: f32,
    pub y: f32,
    pub k: f32,
}

#[derive(Debug, Clone, Copy)]
pub struct Yuv {
    pub y: f32,
    pub u: f32,
    pub v: f32,
}

pub struct ColorConverter;

impl ColorConverter {
    pub fn rgb_to_hsl(rgb: &Rgb) -> Hsl {
        let (r, g, b) = (rgb.r, rgb.g, rgb.b);
        let max = cpp_max(cpp_max(r, g), b);
        let min = cpp_min(cpp_min(r, g), b);

        let l = (max + min) / 2.0;

        let mut h = 0.0f32;
        let mut s = 0.0f32;
        if max != min {
            let d = max - min;
            s = if l <= 0.5 {
                d / (max + min)
            } else {
                d / (2.0 - max - min)
            };
            if r == max {
                let q = (g - b) / d;
                h = if b > g { 6.0 + q } else { q };
            } else if g == max {
                h = 2.0 + (b - r) / d;
            } else {
                h = 4.0 + (r - g) / d;
            }
            h = h / 6.0;
            h = 360.0 * h;
        }
        Hsl { h, s, l }
    }

    pub fn rgb_to_hsv(rgb: &Rgb) -> Hsv {
        let (r, g, b) = (rgb.r, rgb.g, rgb.b);
        let max = cpp_max(cpp_max(r, g), b);
        let min = cpp_min(cpp_min(r, g), b);

        let v = max;
        let d = max - min;

        let s = if max == 0.0 { 0.0 } else { d / max };

        let mut h = 0.0f32;
        if max != min {
            if r == max {
                let q = (g - b) / d;
                h = if b > g { 6.0 + q } else { q };
            } else if g == max {
                h = 2.0 + (b - r) / d;
            } else {
                h = 4.0 + (r - g) / d;
            }
            h = h / 6.0;
            h = 360.0 * h;
        }
        Hsv { h, s, v }
    }

    pub fn rgb_to_cmyk(rgb: &Rgb) -> Cmyk {
        let k = 1.0 - cpp_max(cpp_max(rgb.r, rgb.g), rgb.b);
        if k == 1.0 {
            return Cmyk {
                c: 0.0,
                m: 0.0,
                y: 0.0,
                k,
            };
        }
        Cmyk {
            c: (1.0 - rgb.r - k) / (1.0 - k),
            m: (1.0 - rgb.g - k) / (1.0 - k),
            y: (1.0 - rgb.b - k) / (1.0 - k),
            k,
        }
    }

    pub fn rgb_to_yuv(rgb: &Rgb) -> Yuv {
        Yuv {
            y: 0.299f32 * rgb.r + 0.587f32 * rgb.g + 0.114f32 * rgb.b,
            u: -0.147f32 * rgb.r - 0.289f32 * rgb.g + 0.436f32 * rgb.b,
            v: 0.615f32 * rgb.r - 0.515f32 * rgb.g - 0.1f32 * rgb.b,
        }
    }
}

